pragma solidity >=0.8.0;

contract IntShiftLiteralBounds {
    uint256 public count;

    function sar255() external returns (int256) {
        int256 x = type(int256).min >> 255;
        count += 1;
        return x;
    }

    function sar256() external returns (int256) {
        int256 x = type(int256).min >> 256;
        count += 1;
        return x;
    }

    function shr256u() external returns (uint256) {
        uint256 y = uint256(255) >> 256;
        count += 1;
        return y;
    }

    function sar8() external returns (int8) {
        int8 z = int8(-8) >> 8;
        count += 1;
        return z;
    }
}
